"""Summarize completed page-header experiments; standard library, optional matplotlib.

Run after measurements, not alongside JMH. Missing inputs are allowed, so a census
can be analyzed before timings finish. Every input measurement is retained in CSV;
the pruning and space figures use an explicit, fixed corpus slice. Raw JMH files
remain the authority for samples and run configuration.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
import re
import sys
from collections import defaultdict
from pathlib import Path


PLOT_VARIANTS = (
    "COMMON16", "COMMON24", "COMMON32", "ASCII128", "GRAM1024", "GRAM4096", "FOURGRAM4096"
)
PIPELINES = ("NONE", "LITERAL_ONLY", "PAGE_ONLY", "PAGE_AND_LITERAL")
COLORS = ("#d55e00", "#e69f00", "#a6761d", "#009e73", "#56b4e9", "#0072b2", "#cc79a7")
SYNTHETIC_CORPORA = {"SHORT", "CATALOG", "PROSE", "UNICODE"}
PRUNING_FIELDS = """corpus order values entries_per_page entries_per_row pages variant query operation
needle_utf8_bytes matches true_pages true_entries trigram_oracle_pages fourgram_oracle_pages admitted_pages
admitted_entries literal_candidates page_and_literal_candidates mean_occupancy page_skip_fraction
entry_skip_fraction true_page_oracle_skip_fraction trigram_oracle_skip_fraction fourgram_oracle_skip_fraction
negative_page_false_positive_fraction literal_candidate_skip_fraction combined_candidate_skip_fraction
additional_candidate_skip_fraction_vs_literal""".split()
SPACE_FIELDS = """corpus order values normalized_utf8_bytes entries_per_page entries_per_row pages variant
encoded_bytes native_capacity_bytes accelerator_bytes payload_bytes_per_page framing_bytes_per_page
sidecar_payload_bytes sidecar_framing_bytes sidecar_total_bytes sidecar_payload_bytes_per_entry
sidecar_framing_bytes_per_entry sidecar_total_bytes_per_entry encoded_bytes_per_entry native_bytes_per_entry
modeled_native_growth_preserving_bytes modeled_native_growth_replacing_bytes
modeled_native_growth_preserving_bytes_per_entry modeled_native_growth_replacing_bytes_per_entry
modeled_native_growth_preserving_fraction modeled_native_growth_replacing_fraction
split_pages replacing_split_pages""".split()
METRIC_FIELDS = """source record_index benchmark jmh_mode threads forks samples score score_error score_unit
mean_ms error_ms confidence_low_ms confidence_high_ms""".split()
COUNT_FIELDS = """source line scenario pipeline requested_values actual_values matches decoded_pages decoded_ids
literal_probes materializations encoded_bytes native_capacity_bytes dictionary_file_bytes
diagnostic_dictionary_build_ns diagnostic_summary_build_ns""".split()
SCAN_FIELDS = METRIC_FIELDS + """scenario corpus order entries_per_page variant query pipeline requested_values
actual_values value_count_source ns_per_value count_records counts_consistent matches decoded_pages decoded_ids
literal_probes materializations encoded_bytes native_capacity_bytes dictionary_file_bytes latency_ratio_vs_none
speedup_vs_none latency_ratio_vs_literal_only speedup_vs_literal_only""".split()
BUILD_COUNT_FIELDS = """source line corpus order requested_values actual_values entries_per_page variant build_mode
pages header_bytes checksum conditional_on_preexisting_summaries preexisting_summary_payload_bytes""".split()
BUILD_FIELDS = METRIC_FIELDS + """corpus order requested_values actual_values value_count_source entries_per_page
variant build_mode ns_per_value error_ns_per_value conditional_on_preexisting_summaries
preexisting_summary_payload_bytes""".split()
KEY_VALUE = re.compile(r"(\w+)=([^\s,\]]+)")


def warn(message):
    print(f"analyze: {message}", file=sys.stderr)


def number(value):
    try:
        result = float(value)
        return result if math.isfinite(result) else None
    except (TypeError, ValueError):
        return None


def ratio(numerator, denominator):
    numerator, denominator = number(numerator), number(denominator)
    return numerator / denominator if numerator is not None and denominator and denominator > 0 else None


def skipped(total, admitted):
    fraction = ratio(admitted, total)
    return 1 - fraction if fraction is not None else None


def write_csv(path, fields, rows):
    with path.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def read_census(path):
    if not path.is_file():
        warn(f"{path.name} is missing; census tables will be empty")
        return [], []
    pruning, space = [], {}
    with path.open(newline="", encoding="utf-8") as stream:
        for line, row in enumerate(csv.DictReader(stream), 2):
            try:
                pages, values = int(row["pages"]), int(row["values"])
                admitted, true = int(row["admitted_pages"]), int(row["true_pages"])
                literal, combined = int(row["literal_candidates"]), int(row["page_and_literal_candidates"])
                result = dict(row)
                result.update(
                    page_skip_fraction=skipped(pages, admitted),
                    entry_skip_fraction=skipped(values, row["admitted_entries"]),
                    true_page_oracle_skip_fraction=skipped(pages, true),
                    trigram_oracle_skip_fraction=skipped(pages, row["trigram_oracle_pages"]),
                    fourgram_oracle_skip_fraction=skipped(pages, row["fourgram_oracle_pages"]),
                    negative_page_false_positive_fraction=ratio(admitted - true, pages - true),
                    literal_candidate_skip_fraction=skipped(values, literal),
                    combined_candidate_skip_fraction=skipped(values, combined),
                    additional_candidate_skip_fraction_vs_literal=skipped(literal, combined),
                )
                payload, framing = pages * int(row["payload_bytes"]), pages * int(row["framing_bytes"])
                if payload + framing != int(row["summary_bytes"]):
                    raise ValueError("summary_bytes differs from page count times header bytes")
                allocation = {
                    key: row[key] for key in (
                        "corpus", "order", "values", "normalized_utf8_bytes", "entries_per_page",
                        "entries_per_row", "pages", "variant", "encoded_bytes", "accelerator_bytes",
                        "split_pages", "replacing_split_pages",
                    )
                }
                allocation.update(
                    native_capacity_bytes=row["capacity_bytes"],
                    payload_bytes_per_page=row["payload_bytes"], framing_bytes_per_page=row["framing_bytes"],
                    sidecar_payload_bytes=payload, sidecar_framing_bytes=framing,
                    sidecar_total_bytes=payload + framing,
                    sidecar_payload_bytes_per_entry=ratio(payload, values),
                    sidecar_framing_bytes_per_entry=ratio(framing, values),
                    sidecar_total_bytes_per_entry=ratio(payload + framing, values),
                    encoded_bytes_per_entry=ratio(row["encoded_bytes"], values),
                    native_bytes_per_entry=ratio(row["capacity_bytes"], values),
                )
                for kind in ("preserving", "replacing"):
                    growth = int(row[f"extra_capacity_{kind}_accelerators"])
                    # -1 means splitting is required: never plot or sum it as a saving.
                    growth = growth if growth >= 0 else None
                    allocation[f"modeled_native_growth_{kind}_bytes"] = growth
                    allocation[f"modeled_native_growth_{kind}_bytes_per_entry"] = ratio(growth, values)
                    allocation[f"modeled_native_growth_{kind}_fraction"] = ratio(growth, row["capacity_bytes"])
                key = tuple(row[field] for field in
                            ("corpus", "order", "values", "entries_per_page", "entries_per_row", "variant"))
                if key in space and space[key] != allocation:
                    raise ValueError(f"conflicting space measurements for {key}")
                space[key] = allocation
                pruning.append(result)
            except (KeyError, TypeError, ValueError) as error:
                raise ValueError(f"{path}:{line}: {error}") from error
    return pruning, list(space.values())


def read_log(path, marker):
    """Retain every setup line, including repeated forks, with its source location."""
    if not path.is_file():
        return []
    records, parameters = [], {}
    with path.open(encoding="utf-8", errors="replace") as stream:
        for line, text in enumerate(stream, 1):
            if text.startswith("# Parameters:"):
                parameters = dict(re.findall(r"(\w+)\s*=\s*([^,)]+)", text))
            if marker in text:
                record = dict(KEY_VALUE.findall(text.split(marker, 1)[1]))
                record.update(source=path.name, line=line)
                record["requested_values"] = record.get("size", parameters.get("size", "").strip())
                records.append(record)
    return records


def scan_counts(path):
    names = {
        "actualValues": "actual_values", "decodedPages": "decoded_pages", "decodedIds": "decoded_ids",
        "literalProbes": "literal_probes", "encodedBytes": "encoded_bytes", "capacityBytes": "native_capacity_bytes",
        "dictionaryBytes": "dictionary_file_bytes", "dictionaryBuildNs": "diagnostic_dictionary_build_ns",
        "summaryBuildNs": "diagnostic_summary_build_ns",
    }
    return [{names.get(key, key): value for key, value in row.items()}
            for row in read_log(path, "PAGE_TEXT_COUNTS")]


def build_counts(paths):
    names = {
        "actualValues": "actual_values", "entriesPerPage": "entries_per_page", "mode": "build_mode",
        "headerBytes": "header_bytes",
        "conditionalOnPreexistingCompleteCompatibleSummaries": "conditional_on_preexisting_summaries",
        "preexistingSummaryPayloadBytes": "preexisting_summary_payload_bytes",
    }
    return [{names.get(key, key): value for key, value in row.items()}
            for path in paths for row in read_log(path, "PAGE_TEXT_BUILD")]


def read_jmh(paths):
    for path in paths:
        try:
            records = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(records, list):
                raise ValueError("expected a JMH JSON array")
        except (OSError, ValueError) as error:
            warn(f"cannot read {path.name}: {error}; retry after measurements finish")
            continue
        for index, record in enumerate(records):
            metric = record.get("primaryMetric", {})
            unit = metric.get("scoreUnit", "")
            factor = {"ns/op": 1e-6, "us/op": 1e-3, "µs/op": 1e-3, "ms/op": 1, "s/op": 1000}.get(unit)
            if record.get("mode") != "avgt" or factor is None:
                warn(f"{path.name} row {index}: unsupported mode/unit; retaining raw score without conversion")
                factor = None

            def milliseconds(value):
                value = number(value)
                return value * factor if value is not None and factor is not None else None

            confidence = metric.get("scoreConfidence", [None, None])
            if not isinstance(confidence, list) or len(confidence) != 2:
                confidence = [None, None]
            result = dict(
                source=path.name, record_index=index, benchmark=record.get("benchmark", ""),
                jmh_mode=record.get("mode", ""), threads=record.get("threads"), forks=record.get("forks"),
                samples=sum(len(fork) for fork in metric.get("rawData", [])),
                score=metric.get("score"), score_error=metric.get("scoreError"), score_unit=unit,
                mean_ms=milliseconds(metric.get("score")), error_ms=milliseconds(metric.get("scoreError")),
                confidence_low_ms=milliseconds(confidence[0]), confidence_high_ms=milliseconds(confidence[1]),
            )
            yield result, record.get("params", {})


def value_count(corpus, requested, logged):
    actual = number(logged)
    if actual is not None and actual > 0:
        return int(actual), "setup_log"
    if corpus in SYNTHETIC_CORPORA and number(requested):
        return int(requested), "synthetic_requested_size"
    # The bundled BSBM corpus is capped to available distinct labels, not padded.
    return None, "unknown_without_setup_log"


def scan_measurements(path, counts):
    rows = []
    mechanical = """actual_values matches decoded_pages decoded_ids literal_probes materializations
encoded_bytes native_capacity_bytes dictionary_file_bytes""".split()
    for row, params in read_jmh([path] if path.is_file() else []):
        scenario, pipeline, requested = params.get("scenario", ""), params.get("pipeline", ""), params.get("size", "")
        parts = scenario.split(":")
        if len(parts) != 5:
            warn(f"cannot unpack scenario {scenario!r}; retaining timing without scenario fields")
            parts = ["", "", "", "", ""]
        row.update(zip(("corpus", "order", "entries_per_page", "variant", "query"), parts))
        row.update(scenario=scenario, pipeline=pipeline, requested_values=requested)
        matched = [count for count in counts if count.get("scenario") == scenario
                   and count.get("pipeline") == pipeline
                   and count.get("requested_values", "") in ("", str(requested))]
        row["count_records"] = len(matched)
        consistent = len({tuple(count.get(field, "") for field in mechanical) for count in matched}) <= 1
        row["counts_consistent"] = consistent if matched else None
        if matched and consistent:
            row.update({field: matched[0].get(field, "") for field in mechanical})
        elif matched:
            warn(f"conflicting setup counts for {scenario}/{pipeline}; leaving joined counts empty")
        actual, origin = value_count(row["corpus"], requested, row.get("actual_values"))
        row.update(actual_values=actual, value_count_source=origin,
                   ns_per_value=ratio(number(row["mean_ms"]) * 1e6 if row["mean_ms"] is not None else None, actual))
        rows.append(row)
    baselines = defaultdict(list)
    for row in rows:
        baselines[(row["scenario"], row["requested_values"], row["pipeline"])].append(row)
    for row in rows:
        for pipeline, suffix in (("NONE", "none"), ("LITERAL_ONLY", "literal_only")):
            candidates = baselines.get((row["scenario"], row["requested_values"], pipeline), [])
            # Do not silently pool repeated runs or compare different actual corpus sizes.
            if len(candidates) == 1 and candidates[0]["actual_values"] == row["actual_values"]:
                baseline = candidates[0]["mean_ms"]
                row[f"latency_ratio_vs_{suffix}"] = ratio(row["mean_ms"], baseline)
                row[f"speedup_vs_{suffix}"] = ratio(baseline, row["mean_ms"])
    return rows


def construction_measurements(paths, counts):
    rows = []
    for row, params in read_jmh(paths):
        corpus, requested = params.get("corpus", ""), params.get("size", "")
        mode, variant, entries = params.get("mode", ""), params.get("variant", ""), params.get("entriesPerPage", "")
        matched = [count for count in counts if (count.get("corpus"), count.get("requested_values"),
                   count.get("entries_per_page"), count.get("variant"), count.get("build_mode"))
                   == (corpus, str(requested), str(entries), variant, mode)]
        logged = {count.get("actual_values") for count in matched if count.get("actual_values")}
        actual, origin = value_count(corpus, requested, next(iter(logged)) if len(logged) == 1 else None)
        row.update(corpus=corpus, order="SHUFFLED", requested_values=requested, actual_values=actual,
                   value_count_source=origin, entries_per_page=entries, variant=variant, build_mode=mode,
                   conditional_on_preexisting_summaries=mode == "OR_EXISTING",
                   preexisting_summary_payload_bytes=56 * actual if mode == "OR_EXISTING" and actual else None)
        for source, target in (("mean_ms", "ns_per_value"), ("error_ms", "error_ns_per_value")):
            row[target] = ratio(row[source] * 1e6 if row[source] is not None else None, actual)
        rows.append(row)
    return rows


def save_figure(figure, output, name, plt):
    for extension in ("png", "svg"):
        metadata = {"Date": None} if extension == "svg" else {"Software": "RDF4J page-text experiment"}
        figure.savefig(output / f"{name}.{extension}", dpi=180, bbox_inches="tight", metadata=metadata)
    plt.close(figure)


def plot_pruning(rows, corpus, output, plt):
    rows = [row for row in rows if row["corpus"] == corpus]
    queries = ("contains_absent_word", "contains_rare")
    orders = [order for order in ("SHUFFLED", "CLUSTERED") if any(row["order"] == order for row in rows)]
    if not rows or not orders:
        return
    figure, axes = plt.subplots(len(orders), len(queries), figsize=(13, 4 * len(orders)), squeeze=False)
    for i, order in enumerate(orders):
        for j, query in enumerate(queries):
            axis = axes[i][j]
            selection = [row for row in rows if row["order"] == order and row["query"] == query]
            for variant, color in zip(PLOT_VARIANTS, COLORS):
                points = sorted((int(row["entries_per_page"]), 100 * row["page_skip_fraction"])
                                for row in selection if row["variant"] == variant)
                if points:
                    axis.plot(*zip(*points), marker=".", color=color, linewidth=1.5, label=variant)
            unique = {int(row["entries_per_page"]): row for row in selection}
            for field, label, color, style in (
                ("true_page_oracle_skip_fraction", "True-hit oracle (upper bound)", "#222222", "--"),
                ("trigram_oracle_skip_fraction", "Exact 3-gram union", "#777777", ":"),
                ("fourgram_oracle_skip_fraction", "Exact 4-gram union", "#663399", ":"),
            ):
                points = [(entries, 100 * row[field]) for entries, row in sorted(unique.items())]
                if points:
                    axis.plot(*zip(*points), color=color, linestyle=style, linewidth=1.4, label=label)
            axis.set(title=f"{order} / {query}", xlabel="Entries per page", ylabel="Pages skipped (%)", ylim=(-3, 103))
            axis.set_xscale("log", base=4)
            axis.set_xticks(sorted(unique), [f"{entries:,}" for entries in sorted(unique)])
            axis.grid(alpha=0.2)
    handles, labels = axes[0][0].get_legend_handles_labels()
    figure.legend(handles, labels, loc="lower center", ncol=4, fontsize=9)
    figure.suptitle(f"Page pruning — {corpus}; fixed absent-word and rare-word queries")
    figure.tight_layout(rect=(0, 0.2 if len(orders) == 1 else 0.12, 1, 0.95))
    save_figure(figure, output, "pruning", plt)


def plot_scans(rows, output, plt):
    groups = defaultdict(list)
    for row in rows:
        if row["mean_ms"] is not None and row["mean_ms"] > 0:
            groups[(row["scenario"], str(row["requested_values"]))].append(row)
    if not groups:
        return
    figure, axis = plt.subplots(figsize=(13, max(4, 0.8 * len(groups) + 2)))
    labels = []
    for index, (key, measurements) in enumerate(sorted(groups.items())):
        sample = measurements[0]
        labels.append(f"{sample['corpus']} / {sample['order']} / {sample['entries_per_page']} / {sample['variant']}\n"
                      f"{sample['query']} (values={sample['actual_values'] or 'unknown'})")
        for pipeline_index, pipeline in enumerate(PIPELINES):
            for row in (item for item in measurements if item["pipeline"] == pipeline):
                mean, low, high = row["mean_ms"], row["confidence_low_ms"], row["confidence_high_ms"]
                error = None
                if low is not None and high is not None and 0 < low <= mean <= high:
                    error = [[mean - low], [high - mean]]
                axis.errorbar(mean, index + (pipeline_index - 1.5) * 0.17, xerr=error, fmt="o", capsize=2,
                              color=("#777777", "#0072b2", "#d55e00", "#009e73")[pipeline_index],
                              label=pipeline if index == 0 else None, markersize=4)
    axis.set_yticks(range(len(labels)), labels, fontsize=8)
    axis.invert_yaxis()
    axis.set_xscale("log")
    axis.set(xlabel="Complete scan time (ms, logarithmic scale)",
             title="Warm-cache scan timings — all measured scenarios and pipelines")
    axis.grid(axis="x", alpha=0.2)
    axis.legend(loc="upper center", bbox_to_anchor=(0.5, -0.06), ncol=4, fontsize=9)
    figure.text(0.5, 0.005,
                "Points: JMH averages. Whiskers: reported confidence intervals when both endpoints are positive.",
                ha="center", fontsize=8)
    figure.tight_layout(rect=(0, 0.04, 1, 1))
    save_figure(figure, output, "scan-latencies", plt)


def plot_space(rows, corpus, output, plt):
    rows = [row for row in rows if row["corpus"] == corpus and row["order"] == "SHUFFLED"]
    if not rows:
        return
    figure, axes = plt.subplots(1, 3, figsize=(15, 5))
    for variant, color in zip(PLOT_VARIANTS, COLORS):
        selection = sorted((row for row in rows if row["variant"] == variant),
                           key=lambda row: int(row["entries_per_page"]))
        fields = ("sidecar_total_bytes_per_entry", "modeled_native_growth_preserving_bytes_per_entry",
                  "modeled_native_growth_replacing_bytes_per_entry")
        for axis, field in zip(axes, fields):
            x = [int(row["entries_per_page"]) for row in selection]
            y = [row[field] if row[field] is not None else math.nan for row in selection]
            if x:
                axis.plot(x, y, marker=".", color=color, linewidth=1.5, label=variant)
        if selection:
            axes[0].plot([int(row["entries_per_page"]) for row in selection],
                         [row["sidecar_payload_bytes_per_entry"] for row in selection],
                         color=color, linestyle=":", linewidth=1)
    for axis, title in zip(axes, ("Raw sidecar header bytes", "Modeled native growth\nretaining accelerators",
                                  "Modeled native growth\nreplacing accelerators (lower bound)")):
        axis.set(title=title, xlabel="Entries per page", ylabel="Additional bytes per entry")
        axis.set_xscale("log", base=4)
        entries = sorted({int(row["entries_per_page"]) for row in rows})
        axis.set_xticks(entries, [f"{value:,}" for value in entries])
        axis.grid(alpha=0.2)
    axes[0].set_yscale("log")
    axes[1].set_yscale("symlog", linthresh=0.01)
    axes[2].set_yscale("symlog", linthresh=0.01)
    handles, labels = axes[0].get_legend_handles_labels()
    figure.legend(handles, labels, loc="lower center", ncol=7, fontsize=8)
    figure.suptitle(f"Space per entry — {corpus} / SHUFFLED; native capacity is RAM, not LMDB disk")
    figure.text(0.5, 0.075,
                "Sidecar: solid = payload + framing, dotted = payload. "
                "Native growth uses actual page sizes and allocator classes.\n"
                "Split-required points have no estimate. "
                "Replacing accelerators does not measure their lost lookup performance.",
                ha="center", fontsize=8)
    figure.tight_layout(rect=(0, 0.14, 1, 0.94))
    save_figure(figure, output, "space-per-entry", plt)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--results", type=Path, default=Path(__file__).resolve().parent / "results")
    parser.add_argument("--output", type=Path, help="default: RESULTS/analysis")
    parser.add_argument("--plot-corpus", default="CATALOG",
                        help="explicit census plot slice; CSV always includes all rows")
    parser.add_argument("--no-plots", action="store_true", help="produce CSV and notes without importing matplotlib")
    args = parser.parse_args()
    output = args.output or args.results / "analysis"
    output.mkdir(parents=True, exist_ok=True)
    pruning, space = read_census(args.results / "census.csv")
    counts = scan_counts(args.results / "scans.log")
    scans = scan_measurements(args.results / "scans.json", counts)
    construction_counts = build_counts(sorted(args.results.glob("construction*.log")))
    construction = construction_measurements(sorted(args.results.glob("construction*.json")), construction_counts)
    tables = (
        ("pruning.csv", PRUNING_FIELDS, pruning), ("space.csv", SPACE_FIELDS, space),
        ("scan-latencies.csv", SCAN_FIELDS, scans), ("scan-counts.csv", COUNT_FIELDS, counts),
        ("construction.csv", BUILD_FIELDS, construction),
        ("construction-counts.csv", BUILD_COUNT_FIELDS, construction_counts),
    )
    for name, fields, rows in tables:
        write_csv(output / name, fields, rows)
        print(f"{name}: {len(rows)} rows")
    notes = f"""PAGE TEXT HEADER EXPERIMENT ANALYSIS

All available census query/variant rows and JMH records are retained in CSV.
Space rows remove repeated query copies of identical measurements; no averaging.
Plots use {args.plot_corpus}; pruning shows the fixed contains_absent_word and
contains_rare queries in both orders. Scan plots include every measured scenario.

Fractions are 0..1; blank means unavailable/undefined, including zero denominators.
True-hit oracle is a theoretical page-skipping ceiling. Gram oracles are exact
unions of grams across a page, not exact per-literal substring indexes.

CSF encoded_bytes and native_capacity_bytes describe actual unmodified pages.
Native capacity is allocated native MEMORY, not LMDB disk. Directory and routing
overheads are excluded. Extra native growth is a capacity-class calculation using
actual encoded pages; a new persisted page format was not allocated or measured.
Split-required layouts have blank growth estimates. Replacing optional accelerators
is a space lower bound; no lost lookup performance is included. Sidecar payload
and framing bytes exclude Java arrays, references, allocator, and object overhead.
dictionary_file_bytes in scan counts concerns the separate temporary LMDB dictionary.

JMH latencies are per complete scan/build, not per page. Ratios use matching scenario
and requested/actual dataset sizes; no independent runs are pooled. Latency ratio
below 1 means faster; speedup above 1 means faster. Ratios are point estimates, not
confidence intervals. JMH score/error/confidence units are explicitly retained.
Per-value figures use logged actual size or the synthetic corpus's exact requested
size. BSBM requested size is not used as a substitute for its capped actual size.
NORMALIZE includes whole-string lowercasing; NORMALIZED assumes normalized labels.
OR_EXISTING assumes complete compatible existing 56-byte literal summaries: creating
or fetching those summaries is excluded from its timed build. Census build_ns and
setup dictionary/summary build times are diagnostics, not JMH results.

Missing inputs yield empty tables. Run analysis again after measurements finish.
Run this script separately from JMH to avoid adding measurement interference.
"""
    (output / "notes.txt").write_text(notes, encoding="utf-8")
    if not args.no_plots:
        try:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as plt
        except ImportError:
            warn("matplotlib is unavailable; CSV summaries are complete, figures skipped")
        else:
            plt.rcParams.update({"font.size": 10, "svg.hashsalt": "rdf4j-page-text-headers"})
            plot_pruning(pruning, args.plot_corpus, output, plt)
            plot_scans(scans, output, plt)
            plot_space(space, args.plot_corpus, output, plt)


if __name__ == "__main__":
    main()
